// plugins/withCloudKit.js
// Native config for CloudKit sync (patches 1 and 2 in docs/CLOUDKIT_SYNC_PLAN.md). The ios/ folder is regenerated by
// `npm run ios:reset`, so this config lives here and never in the generated project.
//
// It does four things:
//   1. Adds the iCloud container and CloudKit entitlement, so the app may open its own zone.
//   2. Sets CKSharingSupported and the remote-notification background mode, so a till can accept the share the owner sends
//      and hear about new records while it is open (the subscriptions themselves come in a later patch).
//   3. Raises the iOS deployment target to 17, which CKSyncEngine needs. It sets both the Podfile platform and the Xcode
//      build setting, because the Podfile alone does not change the app target.
//   4. Adds the AppDelegate method iOS calls when someone taps a CloudKit share link on this device
//      (`userDidAcceptCloudKitShareWith`). Expo forwards a fixed set of delegate calls and this is not one of them, so the
//      method has to be written into the generated AppDelegate. It only records the link and points at the CloudKit
//      module, which does the accepting (patch 2 of docs/CLOUDKIT_SYNC_PLAN.md).
// The aps-environment entitlement is deliberately left out until the push subscriptions land (a later patch), because an
// app with it must also be signed with a push-enabled profile.
const { withEntitlementsPlist, withInfoPlist, withPodfileProperties, withXcodeProject, withAppDelegate } = require('@expo/config-plugins');

const CONTAINER = 'iCloud.com.aidens3dp.pos';
const DEPLOYMENT_TARGET = '17.0';

// The key the CloudKit module reads: a share link that opened the app, kept for a cold launch.
const PENDING_INVITE_KEY = 'cloudkitPendingInvite';
// The note the CloudKit module listens for, so a warm app joins the moment the link is tapped.
const SHARE_NOTIFICATION = 'cloudkitDidAcceptShare';
const SHARE_MARKER = '// CloudKit share links (added here by plugins/withCloudKit.js).';

const withIcloudEntitlements = (config) =>
  withEntitlementsPlist(config, (c) => {
    c.modResults['com.apple.developer.icloud-container-identifiers'] = [CONTAINER];
    c.modResults['com.apple.developer.icloud-services'] = ['CloudKit'];
    return c;
  });

const withSharingSupport = (config) =>
  withInfoPlist(config, (c) => {
    c.modResults.CKSharingSupported = true;
    c.modResults.UIBackgroundModes = [...new Set([...(c.modResults.UIBackgroundModes ?? []), 'remote-notification'])];
    return c;
  });

const withPodfileTarget = (config) =>
  withPodfileProperties(config, (c) => {
    c.modResults['ios.deploymentTarget'] = DEPLOYMENT_TARGET;
    return c;
  });

const withProjectTarget = (config) =>
  withXcodeProject(config, (c) => {
    for (const entry of Object.values(c.modResults.pbxXCBuildConfigurationSection())) {
      const bs = entry && entry.buildSettings;
      if (bs && bs.IPHONEOS_DEPLOYMENT_TARGET !== undefined) bs.IPHONEOS_DEPLOYMENT_TARGET = DEPLOYMENT_TARGET;
    }
    return c;
  });

// iOS calls this when a share link is tapped on the device. It records the link (for a launch that has not loaded the
// CloudKit module yet) and hands the metadata to the module, which does the accepting. The method is added inside the
// AppDelegate class, and the marker keeps a second run of prebuild from adding it twice.
//
// This is a plain text transform on purpose: it takes the AppDelegate's text and gives the text back, so the node tests
// can check the result without a build. An Objective-C AppDelegate (not what this project generates) is left alone rather
// than having Swift written into it, and an AppDelegate that already carries the marker is returned unchanged.

/** The braces that hold a class body: the `{` after `marker` and the `}` that closes it. Null when either is missing. */
function classBody(contents, marker) {
  const start = contents.search(marker);
  if (start < 0) return null;
  const open = contents.indexOf('{', start);
  if (open < 0) return null;
  let depth = 0;
  for (let i = open; i < contents.length; i += 1) {
    if (contents[i] === '{') depth += 1;
    else if (contents[i] === '}') {
      depth -= 1;
      if (depth === 0) return { close: i };
    }
  }
  return null;
}

function injectShareLinkHandler(contents, language = 'swift') {
  if (language !== 'swift') return contents;
  if (contents.includes(SHARE_MARKER)) return contents;
  const withImport = /^\s*import CloudKit\s*$/m.test(contents)
    ? contents
    : contents.replace(/^(\s*import [^\n]+\n)/m, `$1import CloudKit\n`);
  // The generated AppDelegate.swift holds a second class (ReactNativeDelegate) after AppDelegate, so the file's last
  // brace is the wrong place: the method must go inside AppDelegate's own braces or iOS never calls it.
  const body = classBody(withImport, /class\s+AppDelegate\b/);
  if (!body) return contents;
  const handler = [
    '',
    `  ${SHARE_MARKER}`,
    '  // @objc is explicit on purpose: the runtime finds the method by selector, and the superclass does not declare it,',
    '  // so nothing else would expose it to UIKit.',
    '  @objc public func application(_ application: UIApplication, userDidAcceptCloudKitShareWith metadata: CKShare.Metadata) {',
    '    if let url = metadata.share.url?.absoluteString {',
    `      UserDefaults.standard.set(url, forKey: "${PENDING_INVITE_KEY}")`,
    '    }',
    `    NotificationCenter.default.post(name: Notification.Name("${SHARE_NOTIFICATION}"), object: metadata)`,
    '  }',
    '',
  ].join('\n');
  return withImport.slice(0, body.close) + handler + withImport.slice(body.close);
}

const withShareLinkHandler = (config) =>
  withAppDelegate(config, (c) => {
    c.modResults.contents = injectShareLinkHandler(c.modResults.contents, c.modResults.language);
    return c;
  });

module.exports = (config) => withShareLinkHandler(withProjectTarget(withPodfileTarget(withSharingSupport(withIcloudEntitlements(config)))));
module.exports.injectShareLinkHandler = injectShareLinkHandler;
